import{_ as d,a0 as p,w as o,s as r,I as t,x as e,a1 as a,A as n,ao as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"Linux 初学者：移动文件 | LCTT x X-CMD","titleTemplate":false,"description":"Linux 初学者：移动文件 | LCTT (201904) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 初学者：移动文件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 初学者：移动文件 | LCTT (201904) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201904/20180828 Linux for Beginners- Moving Things Around","title":"Linux 初学者：移动文件","tag":"201904","desc":""},"relativePath":"201904/20180828 Linux for Beginners- Moving Things Around.md","filePath":"[post].md"}'),g={name:"201904/20180828 Linux for Beginners- Moving Things Around.md"};function h(c,s,k,u,b,m){const i=p("Link");return o(),r("div",null,[s[38]||(s[38]=t("h1",{id:"linux-初学者-移动文件",tabindex:"-1"},[e("Linux 初学者：移动文件 "),t("a",{class:"header-anchor",href:"#linux-初学者-移动文件","aria-label":"Permalink to “Linux 初学者：移动文件”"},"​")],-1)),s[39]||(s[39]=t("p",null,[t("img",{src:"https://www.linux.com/sites/lcom/files/styles/rendered_file/public/filesystem-linux.jpg?itok=NQCoYl1f",alt:""})],-1)),t("p",null,[s[3]||(s[3]=e("在之前的该系列的部分中，",-1)),a(i,{href:"https://linux.cn/article-10066-1.html"},{default:n(()=>[...s[0]||(s[0]=[e("你学习了有关目录",-1)])]),_:1}),s[4]||(s[4]=e("和",-1)),a(i,{href:"https://linux.cn/article-10399-1.html"},{default:n(()=>[...s[1]||(s[1]=[e("访问目录",-1)])]),_:1}),a(i,{href:"https://linux.cn/article-10370-1.html"},{default:n(()=>[...s[2]||(s[2]=[e("的权限",-1)])]),_:1}),s[5]||(s[5]=e("是如何工作的。你在这些文章中学习的大多数内容都可应用于文件，除了如何让一个文件变成可执行文件。",-1))]),s[40]||(s[40]=l('<p>因此让我们在开始之前先解决这个问题。</p><h3 id="不需要-exe-扩展名" tabindex="-1">不需要 .exe 扩展名 <a class="header-anchor" href="#不需要-exe-扩展名" aria-label="Permalink to “不需要 .exe 扩展名”">​</a></h3><p>在其他操作系统中，一个文件的性质通常由它的后缀决定。如果一个文件有一个 .jpg 扩展，操作系统会认为它是一幅图像；如果它以 .wav 结尾，它是一个音频文件；如果它在文件名末尾以 .exe 结尾，它就是一个你可以执行的程序。</p><p>这导致了严重的问题，比如说木马可以伪装成文档文件。幸运的是，在 Linux 下事物不是这样运行的。可以确定的是，你可能会看到有些可执行文件是以 .sh 结尾暗示它们是可执行的脚本，但是这大部分是为了便于人眼找到文件，就像你使用 <code>ls --color</code> 将可执行文件的名字以亮绿色显示的方式相同。</p><p>事实上大多数应用根本没有扩展名。决定一个文件是否是一个真正程序的是 <code>x</code> （指<em>可执行的</em>）位。你可以通过运行以下命令使任何文件变得可执行，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>chmod a+x some_program</span></span></code></pre></div><p>而不管它的扩展名是什么或者是否存在。在上面命令中的 <code>x</code> 设置了 <code>x</code> 位，<code>a</code> 说明你为<em>所有</em>用户设置它。你同样可以为一组用户设置成拥有这个文件（<code>g+x</code>），或者只为一个用户——拥有者——设置 （<code>u+x</code>）。</p><p>尽管我们会在该系列之后的部分包含从命令行创建和运行脚本的内容，并学习通过输入它的路径并在结尾加上程序名的方式运行一个程序：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>path/to/directory/some_program</span></span></code></pre></div><p>或者，如果你当前在相同目录，你可以使用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>./some_program</span></span></code></pre></div><p>还有其他方式可以使你的程序在目录树的任意位置运行 （提示：查询 <code>$PATH</code> 环境变量），但是当我们讨论 shell 脚本的时候你会读到这些。</p><h3 id="复制、移动、链接" tabindex="-1">复制、移动、链接 <a class="header-anchor" href="#复制、移动、链接" aria-label="Permalink to “复制、移动、链接”">​</a></h3><p>明显地，从命令行修改和处理文件有很多的方式，而不仅仅是处理它们的权限。当你试图打开一个不存在的文件是，大多数应用会创建一个新文件。如果 <code>test.txt</code> 当前并不存在，下列命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>nano test.txt</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>vim test.txt</span></span></code></pre></div>',16)),t("p",null,[s[8]||(s[8]=e("（",-1)),a(i,{href:"https://www.nano-editor.org/"},{default:n(()=>[...s[6]||(s[6]=[e("nano",-1)])]),_:1}),s[9]||(s[9]=e(" 和 ",-1)),a(i,{href:"https://www.vim.org/"},{default:n(()=>[...s[7]||(s[7]=[e("vim",-1)])]),_:1}),s[10]||(s[10]=e(" 是流行的命令行文本编辑器）都将为你创建一个空的 ",-1)),s[11]||(s[11]=t("code",null,"test.txt",-1)),s[12]||(s[12]=e(" 文件来编辑。",-1))]),s[41]||(s[41]=l(`<p>你可以通过 “触摸” （<code>touch</code>）来创建一个空的文件，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>touch test.txt</span></span></code></pre></div><p>会创建一个文件，但是不会在任何应用中打开它。</p><p>你可以使用 <code>cp</code> 来拷贝一个文件到另一个位置，或者使用一个不同的名字：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cp test.txt copy_of_test.txt</span></span></code></pre></div><p>你也可以拷贝一堆文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cp *.png /home/images</span></span></code></pre></div><p>上面的命令拷贝当前目录下的所有 PNG 文件到相对你的主目录下的 <code>images/</code> 目录。在你尝试之前 <code>images/</code> 目录必须存在， 不然 <code>cp</code> 将显示一个错误。同样的，警惕，当你复制一个文件到一个已经包含相同名字的文件的目录时，<code>cp</code> 会静默地用新文件覆盖老的文件。</p><p>你可以使用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cp -i *.png /home/images</span></span></code></pre></div><p>如果你想要 <code>cp</code> 命令在有任何危险时警告你 （<code>-i</code> 选项代表<em>交互式的</em>）。</p><p>你同样可以复制整个目录，但是为了做到这样，你需要 <code>-r</code> 选项：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cp -rv directory_a/ directory_b</span></span></code></pre></div><p><code>-r</code> 选项代表<em>递归</em>，意味着 <code>cp</code> 会向下探索目录 <code>directory_a</code>，复制所有的文件和子目录下内部包含的。我个人喜欢包含 <code>-v</code> 选项，因为它使 <code>cp</code> 冗长而啰嗦，意味着它会显示你当前它正在做什么而不是仅仅静默的复制然后存在。</p><p><code>mv</code> 命令移动东西。也就是说，它移动文件从一个位置到另一个位置。最简单的形式，<code>mv</code> 表现的更像 <code>cp</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mv test.txt new_test.txt</span></span></code></pre></div><p>上面的命令使 <code>new_test.txt</code> 出现，<code>test.txt</code> 消失。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mv *.png /home/images</span></span></code></pre></div><p>移动当前目录下所有的 PNG 文件到相对于你的主目录的 <code>images/</code> 目录。同样的你必须小心你没有意外的覆盖已存在的文件。使用</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mv -i *.png /home/images</span></span></code></pre></div><p>如果你想站在安全的角度，你可以使用与 <code>cp</code> 相同的方式。</p><p>除了移动与拷贝的不同外，另一个 <code>mv</code> 和 <code>cp</code> 之间的不同是当你移动目录时：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mv directory_a/ directory_b</span></span></code></pre></div><p>不需要添加递归的标志。这是因为你实际做的是重命名一个目录，与第一个例子相同，你做的是重命名文件。实际上，即使你从一个目录到另一个目录 “移动” 一个文件，只要两个目录在相同的存储设备和分区，你就是在重命名文件。</p><p>你可以做一个实验来证明。 <code>time</code> 是一个工具来让你测量一个命令花费多久来执行。找一个非常大的文件，可以是几百 MB 甚至 几 GB （例如一个长视频），像下方这样尝试拷贝到另一个目录：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ time cp hefty_file.mkv another_directory/</span></span>
<span class="line"><span>real 0m3,868s</span></span>
<span class="line"><span>user 0m0,016s</span></span>
<span class="line"><span>sys 0m0,887s</span></span></code></pre></div><p>下面是 <code>time</code> 的输出。需要关注的是第一行， real 时间。它花费了几乎 4 秒来拷贝 355 MB 的 <code>hefty_file.mkv</code> 到 <code>another_directory/</code> 目录。</p><p>现在让我们尝试移动它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ time mv hefty_file.mkv another_directory/</span></span>
<span class="line"><span>real 0m0,004s</span></span>
<span class="line"><span>user 0m0,000s</span></span>
<span class="line"><span>sys 0m0,003s</span></span></code></pre></div><p>移动几乎是瞬时的！这是违反直觉的，因为看起来 <code>mv</code> 必须复制这个文件然后删除原来的。这是 <code>mv</code> 对比 <code>cp</code> 命令必须做的两件事。但是，实际上，<code>mv</code> 快了 1000 倍。</p>`,30)),t("p",null,[s[14]||(s[14]=e("这是因为文件系统结构中，它的所有目录树，只为了让用户便利而存在。在每个分区的开始，有一个称作",-1)),s[15]||(s[15]=t("em",null,"分区表",-1)),s[16]||(s[16]=e("的东西告诉操作系统在实际的物理磁盘上去哪找每个文件。在磁盘上，数据没有分为目录甚至是文件。",-1)),a(i,{href:"https://en.wikipedia.org/wiki/Disk_sector"},{default:n(()=>[...s[13]||(s[13]=[e("作为替代的是轨道、扇区和簇",-1)])]),_:1}),s[17]||(s[17]=e("。当你在相同分区 “移动” 一个文件时，操作系统实际做的仅仅是在分区表中改变了那个文件的入口，但它仍然指向磁盘上相同的簇信息。",-1))]),s[42]||(s[42]=l('<p>是的！移动是一个谎言！至少在相同分区下是。如果你试图移动一个文件到一个不同的分区或者不同的设备， <code>mv</code> 仍然很快，但可以察觉到它比在相同分区下移动文件慢了。这是因为实际上发生了复制和清除数据。</p><h3 id="重命名" tabindex="-1">重命名 <a class="header-anchor" href="#重命名" aria-label="Permalink to “重命名”">​</a></h3><p>有几个不同的命令行 <code>rename</code> 工具。没有一个像 <code>cp</code> 和 <code>mv</code> 那样固定，并且它们工作的方式都有一点不同，相同的一点是它们都被用来改变文件名的部分。</p>',3)),t("p",null,[s[19]||(s[19]=e("在 Debian 和 Ubuntu 中， 默认的 ",-1)),s[20]||(s[20]=t("code",null,"rename",-1)),s[21]||(s[21]=e(" 工具使用 ",-1)),a(i,{href:"https://en.wikipedia.org/wiki/Regular_expression"},{default:n(()=>[...s[18]||(s[18]=[e("正则表达式",-1)])]),_:1}),s[22]||(s[22]=e("（字符组成的字符串模式）来大量的改变目录中的文件。命令：",-1))]),s[43]||(s[43]=l('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>rename &#39;s/\\.JPEG$/.jpg/&#39; *</span></span></code></pre></div><p>将改变所有扩展名为 <code>JPEG</code> 的文件为 <code>jpg</code>。文件 <code>IMG001.JPEG</code> 变成 <code>IMG001.jpg</code>、 <code>my_pic.JPEG</code> 变成 <code>my_pic.jpg</code>，等等。</p><p>另一个 <code>rename</code> 版本默认在 Manjaro 上可获得，这是一个 Arch 的衍生版，更简单，但是可能没有那么强大：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>rename .JPEG .jpg *</span></span></code></pre></div><p>这和你之前看到的上面做相同的重命名操作。在这个版本，<code>.JPEG</code> 是你想改变的字符组成的字符串，<code>.jpg</code> 是你想要改变成为的，<code>*</code> 表示当前目录下的所有文件。</p><p>基本原则是如果你所做的仅仅是重命名一个文件或者目录，你最好用 <code>mv</code>，这是因为 <code>mv</code> 在所有分发版上都是可靠一致的。</p><h3 id="了解更多" tabindex="-1">了解更多 <a class="header-anchor" href="#了解更多" aria-label="Permalink to “了解更多”">​</a></h3><p>查看 <code>mv</code> 和 <code>cp</code> 的 man 页面了解更多。运行</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>man cp</span></span></code></pre></div><p>或者</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>man mv</span></span></code></pre></div><p>来阅读这些命令自带的所有选项，这些使他们使用起来更强大和安全。</p><hr>',13)),t("p",null,[s[24]||(s[24]=e("via: ",-1)),a(i,{href:"https://www.linux.com/blog/2018/8/linux-beginners-moving-things-around"},{default:n(()=>[...s[23]||(s[23]=[e("https://www.linux.com/blog/2018/8/linux-beginners-moving-things-around",-1)])]),_:1})]),t("p",null,[s[29]||(s[29]=e("作者：",-1)),a(i,{href:"https://www.linux.com/users/bro66"},{default:n(()=>[...s[25]||(s[25]=[e("Paul Brown",-1)])]),_:1}),s[30]||(s[30]=e(" 选题：",-1)),a(i,{href:"https://github.com/lujun9972"},{default:n(()=>[...s[26]||(s[26]=[e("lujun9972",-1)])]),_:1}),s[31]||(s[31]=e(" 译者：",-1)),a(i,{href:"https://github.com/warmfrog"},{default:n(()=>[...s[27]||(s[27]=[e("warmfrog",-1)])]),_:1}),s[32]||(s[32]=e(" 校对：",-1)),a(i,{href:"https://github.com/wxy"},{default:n(()=>[...s[28]||(s[28]=[e("wxy",-1)])]),_:1})]),t("p",null,[s[35]||(s[35]=e("本文由 ",-1)),a(i,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[33]||(s[33]=[e("LCTT",-1)])]),_:1}),s[36]||(s[36]=e(" 原创编译，",-1)),a(i,{href:"https://linux.cn/"},{default:n(()=>[...s[34]||(s[34]=[e("Linux中国",-1)])]),_:1}),s[37]||(s[37]=e(" 荣誉推出",-1))])])}const v=d(g,[["render",h]]);export{y as __pageData,v as default};
